// contractAssertBeginSmoke asserts Begin survives a call.
func contractAssertBeginSmoke(
	tb testing.TB,
	c Contract,
) {
	tb.Helper()
	suite.Survives(tb, contractBegin, func(ctx context.Context) {
		_, _ = c.Begin(ctx)
	})
}

// contractAssertBeginCancels asserts Begin reports a cancelled context as cancelled.
func contractAssertBeginCancels(
	tb testing.TB,
	c Contract,
) {
	tb.Helper()
	suite.ReportsCancelled(tb, contractBegin, func(ctx context.Context) error {
		_, err := c.Begin(ctx)
		return err
	})
}

