// contractAssertBeginHonoursDeadline asserts Begin reports an expired deadline as exceeded.
func contractAssertBeginHonoursDeadline(
	tb testing.TB,
	c Contract,
) {
	tb.Helper()
	suite.ReportsDeadlineExceeded(tb, contractBegin, func(ctx context.Context) error {
		_, err := c.Begin(ctx)
		return err
	})
}

// contractAssertBeginZeroOnError asserts Begin returns the zero Tx alongside any error.
func contractAssertBeginZeroOnError(
	tb testing.TB,
	c Contract,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := c.Begin(ctx)
	if err == nil {
		tb.Skip("Begin answered for a cancelled context, so this check has no error to inspect")
	}

	var zero tx.Tx
	if got != zero {
		tb.Errorf("Begin must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

